          "title": "დიალოგი 1: ოფიციალური გაცნობა უნივერსიტეტში (Formell / Sie-Form)",
          "context": "გიორგი ბერიძე პირველად ხვდება გერმანული ენის ლექტორს, ქალბატონ ვაგნერს.",
