          "content_ka": "ბინისა და ავეჯის დასახასიათებლად გამოიყენება ანტონიმური წყვილები:\n• **groß** (დიდი) <-> **klein** (პატარა)\n• **hell** (ნათელი) <-> **dunkel** (ბნელი)\n• **teuer** (ძვირი) <-> **billig / günstig** (იაფი / ხელმისაწვდომი)\n• **ruhig** (მშვიდი, წყნარი) <-> **laut** (ხმაურიანი)\n• **schön** (ლამაზი) <-> **hässlich** (უშნო)\n• **gemütlich** (მყუდრო) <-> **unbequem** (მოუხერხებელი)\n\nზმნა *sein*-თან ზედსართავი სახელი დაბოლოებას **არ იღებს**:\n• *Die Wohnung ist sehr **hell** und **gemütlich**.* (ბინა ძალიან ნათელი და მყუდროა.)",
