          "content_ka": "გერმანიაში ბინის ქირაობისას გადამწყვეტია ამ ტერმინების ცოდნა:\n• **die Kaltmiete:** \"ცივი ქირა\" — მხოლოდ ბინის საფასური გათბობისა და კომუნალურების გარეშე.\n• **die Nebenkosten (NK):** კომუნალური ხარჯები (ნაგავი, ლიფტი, წყალი, სადარბაზოს მოვლა).\n• **die Warmmiete:** \"თბილი ქირა\" — სრული ქირა (Kaltmiete + Nebenkosten + გათბობა). სწორედ ამ თანხას ურიცხავთ გამქირავებელს ყოველთვიურად!\n• **die Kaution:** დეპოზიტი (ჩვეულებრივ 2-3 თვის Kaltmiete), რომელიც ბინის დაცლისას გიბრუნდებათ.",
