          "content_ka": "გერმანულში დროის კითხვა ორნაირად ისმება:\n• *Wie spät ist es?* (რომელი საათია?)\n• *Wie viel Uhr ist es?* (რამდენი საათია?)\n\n**1. ოფიციალური დრო (24-საათიანი - რადიო, ტელევიზია, მატარებლის განრიგი):**\nჯერ საათი, მერე სიტყვა *Uhr*, მერე წუთები:\n• 14:15 = *vierzehn Uhr fünfzehn*\n• 08:30 = *acht Uhr dreißig*\n\n**2. სასაუბრო დრო (12-საათიანი):**\nიყენებს სიტყვებს: **nach** (შემდეგ/გადასული), **vor** (აკლია), **Viertel** (თხუთმეტი წუთი/მეოთხედი), **halb** (ნახევარი).\n• 10:15 = *Viertel **nach** zehn* (თხუთმეტი წუთი თერთმეტისკენ კი არა, ათს გადაცილებული!)\n• 10:45 = *Viertel **vor** elf* (თერთმეტს აკლია თხუთმეტი)\n\n> **⚠️ ქართულენოვანთათვის უდიდესი ხაფანგი: 'halb'**\n> გერმანულში სიტყვა *halb* მიუთითებს **შემდეგ (მომავალ) საათზე**!\n> • *halb zehn* = **09:30** (ათის ნახევარი, ანუ 10-მდე ნახევარი საათი დარჩა!)\n> • *halb acht* = **07:30** (რვის ნახევარი)\n> ქართველებს ხშირად ჰგონიათ, რომ *halb zehn* 10:30-ია — დაიმახსოვრეთ: ყოველთვის ერთით ნაკლებია!",
