          "content_ka": "დროის გამოსახატავად გერმანულში გამოიყენება 3 მთავარი წინდებული:\n• **um** — ზუსტ საათთან: *um 8 Uhr*, *um wie viel Uhr?*\n• **am** (an + dem) — კვირის დღეებთან და დღის მონაკვეთებთან: *am Montag*, *am Wochenende*, *am Morgen*, *am Abend* (გამონაკლისი: *in der Nacht*).\n• **im** (in + dem) — თვეებთან, სეზონებთან და წლებთან: *im Januar*, *im Sommer*, *im Jahr 2026*.",
