          "content_ka": "მოდალური ზმნები გამოხატავს დამოკიდებულებას მოქმედებისადმი (შეძლება, სურვილი, ნებართვა).\nგერმანულში მოდალურ ზმნებს აქვთ 2 უმნიშვნელოვანესი თვისება:\n1. **ich** და **er/sie/es** პირებში ფორმები **სრულიად ერთნაირია** და დაბოლოება **არ აქვთ**!\n2. მხოლობით რიცხვში ფუძისეული ხმოვანი ხშირად იცვლის ფორმას.\n\n| პირი | können (შეძლება/უნარი) | wollen (მტკიცე ნდომა) | möchten (სურვილი/მინდა) |\n| :--- | :--- | :--- | :--- |\n| **ich** | **kann** | **will** | **möchte** |\n| **du** | kannst | willst | möchtest |\n| **er/sie/es** | **kann** | **will** | **möchte** |\n| **wir** | können | wollen | möchten |\n| **ihr** | könnt | wollt | möchtet |\n| **sie/Sie** | können | wollen | möchten |",
