          "content_ka": "ეს არის გერმანული სინტაქსის ფუნდამენტური წესი:\nთუ წინადადებაში არის მოდალური ზმნა:\n• უღლებადი მოდალური ზმნა დგას **მე-2 ადგილზე**!\n• ძირითადი ზმნა გადადის **წინადადების სულ ბოლოში ინფინიტივში (დაუბოლოებელი ფორმით -en)**!\n\n> **⚠️ შეადარეთ ქართულს:**\n> ქართულად ვამბობთ: \"მე შემიძლია **ვილაპარაკო** გერმანულად\".\n> გერმანულად: *Ich **kann** sehr gut Deutsch **sprechen**.* (ზმნა sprechen ბოლოშია!).\n> *Wir **wollen** am Samstag nach Wien **fahren**.* (ჩვენ გვინდა შაბათს ვენაში გამგზავრება).",
