          "title": "7.3 ორიენტაცია ქალაქში: გზის კითხვა და მითითება",
          "content_ka": "როგორ ვიკითხოთ გზა:\n• *Entschuldigung, wie komme ich zum Bahnhof?* (უკაცრავად, როგორ მივიდე ვაგზლამდე?)\n• *Wo ist hier eine Apotheke?* (სად არის აქ აფთიაქი?)\n\nგზის მითითების ფრაზები:\n• **Gehen Sie geradeaus!** (იარეთ პირდაპირ!)\n• **Biegen Sie nach links / nach rechts ab!** (შეუხვიეთ მარცხნივ / მარჯვნივ!)\n• **An der Kreuzung / An der Ampel:** (გზაჯვარედინზე / შუქნიშანზე).",
