          "content_ka": "ტკივილის გამოსახატავად გერმანულში 2 ძირითადი კონსტრუქციაა:\n1. **... tut / tun weh (მტკივა):**\n• თუ ერთი ორგანო მტკივა (მხოლობითი): *Mein Kopf **tut weh**.* (თავი მტკივა), *Mein Bauch **tut weh**.* (მუცელი მტკივა).\n• თუ რამდენიმე ორგანო მტკივა (მრავლობითი): *Meine Augen **tun weh**.* (თვალები მტკივა), *Meine Beine **tun weh**.* (ფეხები მტკივა).\n\n2. **...-schmerzen haben (ტკივილები მაქვს):**\n• *Ich habe Kopfschmerzen.* (თავის ტკივილი მაქვს.)\n• *Ich habe Halsschmerzen.* (ყელის ტკივილი მაქვს.)\n• *Ich habe Fieber und Husten.* (სიცხე და ხველა მაქვს.)",
