          "title": "10.3 Partizip II-ის წარმოება (რეგულარული და არარეგულარული)",
          "content_ka": "Partizip II იწარმოება 3 ძირითადი წესით:\n\n1. **რეგულარული (სუსტი) ზმნები:** **ge- + ფუძე + -t**\n• *machen* -> *ge-mach-t* (გაკეთებული)\n• *kaufen* -> *ge-kauf-t* (ნაყიდი)\n• *lernen* -> *ge-lern-t* (ნასწავლი)\n\n2. **-ieren დაბოლოების ზმნები (არ იღებენ ge-ს!):**\n• *studieren* -> *studier-t* (ნასწავლი)\n• *fotografieren* -> *fotografier-t* (ფოტოგადაღებული)\n\n3. **არარეგულარული (ძლიერი) ზმნები:** ხშირად **ge- + შეცვლილი ფუძე + -en**:\n• *trinken* -> *ge-trunk-en*\n• *schreiben* -> *ge-schrieb-en*\n• *lesen* -> *ge-les-en*\n\n> **📌 დაიმახსოვრეთ:** გერმანული ზმნების სწავლისას ყოველთვის ისწავლეთ მისი პერფექტის ფორმა: *trinken -> hat getrunken*.",
